PROCEDURE sp(para_RAM_MiB IN BINARY_FLOAT, para_WiFi IN VARCHAR2, para_used_kb IN BINARY_FLOAT, para_Pixels IN VARCHAR2) IS result_val PLS_INTEGER := 0;

status_text VARCHAR2(4000) := 'pending';

BEGIN

    IF para_RAM_MiB < 0 THEN

        result_val := ROUND(para_RAM_MiB * - 1);

        UPDATE "chip_model" SET "RAM_MiB" = result_val WHERE "WiFi" = para_WiFi;

    ELSIF para_RAM_MiB < 10 THEN

        result_val := ROUND(para_RAM_MiB + 5);

        DELETE FROM "chip_model" WHERE "RAM_MiB" = para_RAM_MiB;

    ELSIF para_RAM_MiB < 20 THEN

        result_val := ROUND(para_RAM_MiB * 2);

        UPDATE "screen_mode" SET "used_kb" = para_used_kb + result_val WHERE "Pixels" = para_Pixels;

    ELSIF para_RAM_MiB < 30 THEN

        result_val := ROUND(para_RAM_MiB - 8);

        DELETE FROM "screen_mode" WHERE "used_kb" = para_used_kb;

    ELSE

        result_val := ROUND(para_RAM_MiB / 2);

        status_text := 'processed';

    END IF;

    UPDATE "chip_model" SET "WiFi" = para_WiFi || status_text WHERE "RAM_MiB" = para_RAM_MiB;

    result_val := ROUND(result_val + 3);

    UPDATE "screen_mode" SET "Pixels" = para_Pixels || '_updated' WHERE "used_kb" = para_used_kb;

    DELETE FROM "chip_model" WHERE "RAM_MiB" > result_val;

    status_text := 'active';

    UPDATE "screen_mode" SET "used_kb" = para_used_kb + 12 WHERE "Pixels" = para_Pixels;

    UPDATE "chip_model" SET "RAM_MiB" = result_val WHERE "WiFi" = para_WiFi;

    result_val := ROUND(result_val - 7);

    DELETE FROM "screen_mode" WHERE "Pixels" = para_Pixels || '_old';

    UPDATE "chip_model" SET "WiFi" = para_WiFi || '_final' WHERE "RAM_MiB" = para_RAM_MiB;

    status_text := 'completed';

    UPDATE "screen_mode" SET "used_kb" = para_used_kb * 3 WHERE "Pixels" = para_Pixels;

    DELETE FROM "chip_model" WHERE "WiFi" = para_WiFi || status_text;

END sp;

